from PIL import Image

def analyze(path, dark=80, min_a=15, max_a=400):
    im = Image.open(path)
    w,h = im.size
    print(path, w, h)
    px = im.load()
    gray = [[0]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y][:3]
            gray[y][x] = (r+g+b)/3
    vis = [[False]*w for _ in range(h)]
    blobs = []
    for y in range(h):
        for x in range(w):
            if vis[y][x] or gray[y][x] > dark:
                continue
            stack=[(x,y)]
            vis[y][x]=True
            pts=[]
            while stack:
                cx,cy=stack.pop()
                pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not vis[ny][nx] and gray[ny][nx]<=dark:
                        vis[ny][nx]=True
                        stack.append((nx,ny))
            if min_a <= len(pts) <= max_a:
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                bw=max(xs)-min(xs)+1; bh=max(ys)-min(ys)+1
                if 0.4 < bw/bh < 2.5 and bw < 40:
                    blobs.append((len(pts), sum(xs)/len(pts), sum(ys)/len(pts), bw, bh))
    blobs.sort(key=lambda t: (t[2], t[1]))
    for b in blobs:
        print(" ", b)

for p in ["top_015","top_016","top_017","top_001"]:
    analyze(f"/home/robot/captures/{p}.png")
